// ③ 本次单只预算：均分投入额，而不是按目标权重切分。
//    理由：月投 1 万买 2 只 → 每只 5000；若按 w% 分（平安 13.52% → 1352 元），
//    远低于 min_ticket，会被 5 元最低佣金吃掉，也不符合实盘下单习惯。
//    同时受「本次最多买几只」与「单笔下限」共同约束。
const plannedCount = Math.max(1, Math.min(maxBuys, cands.length));
const equalAmt = amount / plannedCount;
const hardCap = Math.min(capRoom, indRoom, mktRoom, poolLeft);
let want = Math.min(equalAmt, hardCap);
// ④ 不够单笔下限时：若额度仍有空间，抬到 min_ticket（避免被最低佣金吃掉）；否则直接跳过
if (want < minTicket) {
  if (hardCap >= minTicket) want = minTicket;
  else { skipped.push({ r: r, why: '额度不足单笔下限（可用 ' + fmt(Math.max(0, hardCap), 0) + ' 元 < ' + fmt(minTicket, 0) + '）' }); return; }
}
const lotCost = r.price * lot;
if (want > 0 && want < lotCost && hardCap >= lotCost) want = lotCost;   // 不够 1 手→抬到 1 手
if (want <= 0) { skipped.push({ r: r, why: '额度已满' }); return; }
const sh = Math.floor(want / r.price / lot) * lot;
if (sh <= 0) { skipped.push({ r: r, why: '额度不足 1 手（' + fmt(lotCost, 0) + ' 元）' }); return; }
const cost = sh * r.price;
const fee = Math.max(cost * (+S.settings.comm || 0), minFee) + cost * (+S.settings.trans || 0);
// ⑤ 摩擦硬门槛：单笔成交额必须 ≥ min_ticket，否则不买（5 元最低佣金占比过高）
if (cost < minTicket) {
  skipped.push({ r: r, why: '单笔 ' + fmt(cost, 0) + ' 元 < 下限 ' + fmt(minTicket, 0) + '，不买' });
  return;
}
items.push({ r: r, shares: sh, cost: cost, fee: fee, lowTicket: false });

