const fs = require('fs'), path = require('path'), vm = require('vm');
const dir = '分析产出/持仓面板';
const https = require('https');
const BASES = ['https://cdn.bootcdn.net/ajax/libs/sql.js/1.13.0/', 'https://cdn.staticfile.org/sql.js/1.13.0/'];
function g(u) { return new Promise((res, rej) => { const r = https.get(u, { headers: { 'User-Agent': 'Mozilla/5.0' } }, x => {
  if (x.statusCode >= 300 && x.statusCode < 400 && x.headers.location) { x.resume(); return g(x.headers.location).then(res, rej); }
  const c = []; x.on('data', d => c.push(d)); x.on('end', () => res(Buffer.concat(c))); });
  r.on('error', rej); r.setTimeout(30000, () => r.destroy(new Error('t'))); }); }
const els = {};
function el(id) { if (!els[id]) els[id] = { innerHTML:'', textContent:'', value:'', style:{}, dataset:{}, classList:{toggle(){},add(){},remove(){},contains(){return false}} }; return els[id]; }
(async () => {
  let SQL = null;
  for (const b of BASES) {
    try { const w = await g(b + 'sql-wasm.wasm'); if (w[0] !== 0) throw 0;
      const s = { console, require, __dirname: process.cwd(), __filename: path.join(process.cwd(),'_s.js'), Uint8Array, Buffer, process, setTimeout, clearTimeout, WebAssembly,
        document: { getElementById: el, querySelector: s2 => el(s2.replace(/^#/,'')), querySelectorAll: () => [], addEventListener(){} } };
      vm.createContext(s); vm.runInContext((await g(b + 'sql-wasm.js')).toString('utf8'), s);
      SQL = await s.initSqlJs({ wasmBinary: new Uint8Array(w) }); break; } catch (e) {}
  }
  if (!SQL) throw new Error('cdn');
  const dbPath = path.join(dir, 'holding.sqlite');
  const db = new SQL.Database(new Uint8Array(fs.readFileSync(dbPath)));
  const w2 = {}; vm.runInNewContext(fs.readFileSync(path.join(dir,'config.js'),'utf8'), { window: w2, console });
  const cfg = w2.PANEL_CONFIG;
  const now = new Date().toISOString();
  db.run("INSERT OR REPLACE INTO setting(k,v) VALUES(?,?)", ['cfg', JSON.stringify(cfg)]);
  db.run("INSERT OR REPLACE INTO setting(k,v) VALUES(?,?)", ['cfgSyncedAt', now]);
  db.run("INSERT OR REPLACE INTO setting(k,v) VALUES(?,?)", ['cfgSource', 'sync']);
  fs.writeFileSync(dbPath, Buffer.from(db.export()));
  console.log('SYNCED min_ticket=' + cfg.rules.min_ticket + ' max_buys=' + cfg.rules.max_buys + ' mode=' + cfg.margin.targetYldMode + ' fixed=' + cfg.margin.targetYldFixed);
})().catch(e => { console.error('ERR', e.message); process.exit(1); });
